import { delegate, type SafeHtml } from 'kerfjs';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { ValueTable } from '@kerfjs/ui/value-table';
import { EmptyState } from '@kerfjs/ui/empty-state';
import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import '@kerfjs/ui/webawesome.css';
import '@awesome.me/webawesome/dist/components/dialog/dialog.js';
import '@awesome.me/webawesome/dist/components/button/button.js';
import './project-dialog.css';

export interface Project { id: string; name: string; summary: string; owner: string; status: string; updated: string }
interface DialogElement extends HTMLElement { open: boolean }
export function mountProjectDialog(root: HTMLElement, app: {
  id: string;
  projects: Project[];
  openProject(id: string): void;
  renderInto(root: HTMLElement, view: SafeHtml): void;
}) {
  let selected = app.projects[0]?.id;
  let open = false;
  let invoker: HTMLElement | null = null;
  const titleId = app.id + '-title';
  const summaryId = app.id + '-summary';
  const dialog = () => root.querySelector<DialogElement>('wa-dialog')!;
  function render() {
    const record = app.projects.find(item => item.id === selected);
    app.renderInto(root, <div class="project-dialog-root kui-layout">
      <button type="button" data-action="projects.show">Compare projects</button>
      <wa-dialog class="project-dialog" label="Project details" without-header open={open}
        aria-labelledby={titleId} aria-describedby={summaryId}>
        <DialogHeader title="Project details" titleId={titleId}
          summary="Choose a project to review its summary and delivery metadata." summaryId={summaryId}
          actions={<wa-button appearance="plain" data-action="projects.close">Close</wa-button>} />
        <div class="project-master-detail kui-dialog-body">
          <nav class="project-master kui-sidebar" aria-label="Projects">
            <MenuHeader label="Available projects" />
            {app.projects.map(project => <MenuItem action="projects.select" itemId={project.id}
              label={project.name} selected={selected === project.id} multiline />)}
          </nav>
          <section class="project-detail kui-section-stack" aria-label="Selected project" aria-live="polite">
            {record ? <>
              <div><h3>{record.name}</h3><p>{record.summary}</p></div>
              <ValueTable label="Project metadata">
                <div><dt>Owner</dt><dd>{record.owner}</dd></div>
                <div><dt>Status</dt><dd>{record.status}</dd></div>
                <div><dt>Updated</dt><dd>{record.updated}</dd></div>
              </ValueTable>
            </> : <EmptyState title="No projects available" detail="Close this dialog and create a project to get started." />}
          </section>
        </div>
        <div slot="footer" class="kui-control-cluster">
          <wa-button appearance="outlined" data-action="projects.close">Cancel</wa-button>
          <wa-button variant="brand" appearance="accent" disabled={!record} data-action="projects.open">Open project</wa-button>
        </div>
      </wa-dialog>
    </div>);
  }
  render();
  const dispose = delegate(root, 'click', '[data-action]', (_event, element) => {
    const node = element as HTMLElement;
    switch (node.dataset.action) {
      case 'projects.show':
        invoker = node; open = true; dialog().open = true; break;
      case 'projects.close': dialog().open = false; break;
      case 'projects.select':
        if (!app.projects.some(item => item.id === node.dataset.itemId)) return;
        selected = node.dataset.itemId; render(); break;
      case 'projects.open':
        if (selected) { dialog().open = false; app.openProject(selected); } break;
    }
  });
  // The production dialog supplies modal focus containment, initial focus and Escape.
  const afterHide = (event: Event) => {
    if (event.target !== dialog()) return;
    open = false;
    if (invoker?.isConnected) invoker.focus();
  };
  root.addEventListener('wa-after-hide', afterHide);
  return () => { dispose(); root.removeEventListener('wa-after-hide', afterHide); };
}

