.project-dialog { --spacing: 0; --width: min(62rem, calc(100vw - 2 * var(--kui-layout-dialog-inset))); }
.project-master-detail { display: grid; grid-template-columns: minmax(12rem, .8fr) minmax(0, 1.4fr); gap: var(--kui-layout-section-gap); min-width: 0; }
.project-master { min-width: 0; border-inline-end: 1px solid var(--kui-color-border); }
.project-detail { min-width: 0; overflow-wrap: anywhere; }
.project-detail h3, .project-detail p { margin: 0; }
.project-detail p { margin-block-start: var(--kui-layout-metadata-gap); }
.project-dialog-root :focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
/* wa-dialog's body is the only scroller. The two columns remain ordinary flow. */
@media (max-width: 48rem) {
  .project-master-detail { grid-template-columns: minmax(0, 1fr); }
  .project-master { border-inline-end: 0; border-block-end: 1px solid var(--kui-color-border); padding-block-end: var(--kui-layout-section-gap); }
}
